import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { _electron as electron, expect, test } from "@playwright/test";
import { startFinoraStub, STUB_CREDENTIALS } from "./finoraStub";

test("customer statement uses real server HTML and prints every document through native IPC", async () => {
  test.setTimeout(90000);
  const outputs = path.resolve(__dirname, "../../../tests/_artifacts/erp-customers");
  // Generated by test_desktop_customers.py using the actual authenticated route.
  const html = readFileSync(path.join(outputs, "statement-real.html"), "utf8");
  const profile = mkdtempSync(path.join(tmpdir(), "finora-customer-print-e2e-"));
  if (
    path.dirname(profile) !== path.resolve(tmpdir()) ||
    !path.basename(profile).startsWith("finora-customer-print-e2e-")
  )
    throw Error("Unsafe test cleanup");
  const stub = await startFinoraStub({ customers: true, customerStatementHtml: html });
  const app = await electron.launch({
    args: [path.resolve(__dirname, "..")],
    cwd: path.resolve(__dirname, ".."),
    env: { ...process.env, FINORA_SERVER_URL: stub.url, FINORA_USER_DATA_DIR: profile },
  });
  try {
    const page = await app.firstWindow();
    await page.getByLabel("معرف الشركة").fill(STUB_CREDENTIALS.tenantSlug);
    await page.getByLabel("اسم المستخدم").fill(STUB_CREDENTIALS.username);
    await page.getByLabel("كلمة المرور").fill(STUB_CREDENTIALS.password);
    await page.getByRole("button", { name: "تسجيل الدخول", exact: true }).click();
    await page.getByRole("button", { name: "العملاء", exact: true }).click();
    const panel = page.getByRole("dialog", { name: "العملاء", exact: true });
    await panel.getByRole("row").filter({ hasText: "أحمد العميل" }).click();
    const details = panel.getByRole("complementary", { name: "أحمد العميل" });
    await details.getByRole("tab", { name: "كشف المستحقات", exact: true }).click();
    const nextWindow = app.waitForEvent("window");
    await details.getByRole("button", { name: "طباعة الكشف / PDF", exact: true }).click();
    const preview = await nextWindow;
    await expect(preview.getByRole("heading", { name: "كشف المستحقات الحالية", exact: true })).toBeVisible();
    await expect(preview.getByRole("table").locator("tbody tr")).toHaveCount(32);
    await expect(preview.getByText("print-document-29", { exact: false })).toBeVisible();
    expect(preview.url()).toBe(`${stub.url}/api/v1/desktop/customers/1/statement/print`);
    await preview.evaluate(() => document.fonts.ready);
    const data = await app.evaluate(async ({ BrowserWindow }) => {
      const win = BrowserWindow.getAllWindows().find((window) =>
        window.webContents.getURL().includes("/statement/print"),
      );
      if (!win) throw Error("Customer print window missing");
      const pdf = await win.webContents.printToPDF({
        printBackground: true,
        preferCSSPageSize: true,
        pageSize: "A4",
      });
      return pdf.toString("base64");
    });
    const pdf = Buffer.from(data, "base64");
    expect(pdf.subarray(0, 5).toString()).toBe("%PDF-");
    expect(pdf.length).toBeGreaterThan(5000);
    mkdirSync(outputs, { recursive: true });
    writeFileSync(path.join(outputs, "customer-statement.pdf"), pdf);
    await preview.screenshot({ path: path.join(outputs, "statement-preview.png"), fullPage: true });
    await preview.close();
  } finally {
    await app.close();
    await stub.close();
    rmSync(profile, { recursive: true, force: true });
  }
});
